	cfg := fakeOAuthConfig(srv.URL)

	var reauthCalled bool
	reauth := func(ctx context.Context, cfg *oauth2.Config) (*oauth2.Token, error) {
		reauthCalled = true
		return nil, errors.New("reauth should not be called")
	}

